});

test('vatSummary includes issued invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary includes partially_paid invoices', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  let issued = issueInvoice(invoice, []).value;
  issued = recordPayment(issued, { amount: 25000, date: '2025-10-20' }).value;
  assert.equal(issued.status, 'partially_paid');

  const result = vatSummary([issued]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary includes paid invoices', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
  }).value;
