test('vatSummary with line discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 20 }], // €850, 20% discount = €170, net €680, VAT 21%: €142.80
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

